132:         return std::unexpected(make_err(ErrCode::FileOpenFailed, error.value()));
133:     }
134: 
135:     std::vector<std::filesystem::path> book_paths;
136:     for (const std::filesystem::directory_entry& entry :
137:         std::filesystem::directory_iterator{directory, error}) {
138:         if (error) {
139:             return std::unexpected(make_err(ErrCode::FileOpenFailed, error.value()));
140:         }
141: 
