239: std::vector<Index> SearchEngine::search_or(std::string_view query) const {
240:     std::vector<Index> matches;
241: 
242:     for (const std::string& word : tokenize(query)) {
243:         const auto found = inverted_index.find(word);
244:         if (found != inverted_index.end()) {
245:             matches.insert(matches.end(), found->second.begin(), found->second.end());
246:         }
