254: std::vector<Index> SearchEngine::search_and(std::string_view query) const {
255:     std::vector<std::string> words;
256:     std::unordered_set<std::string> seen_words;
257: 
258:     for (std::string& word : tokenize(query)) {
259:         if (seen_words.insert(word).second) {
260:             words.emplace_back(std::move(word));
261:         }
262:     }
263: 
264:     if (words.empty()) {
265:         return {};
266:     }
267: 
268:     std::unordered_map<size_t, size_t> book_match_counts;
269: 
270:     for (const std::string& word : words) {
271:         const auto found = inverted_index.find(word);
272:         if (found == inverted_index.end()) {
273:             return {};
274:         }
275: 
276:         std::unordered_set<size_t> matched_books;
277:         for (const Index& index : found->second) {
278:             matched_books.emplace(index.book_id);
279:         }
280: 
281:         for (size_t book_id : matched_books) {
282:             book_match_counts[book_id]++;
283:         }
284:     }
285: 
286:     std::unordered_set<size_t> matched_books;
287:     for (const auto& [book_id, count] : book_match_counts) {
288:         if (count == words.size()) {
289:             matched_books.insert(book_id);
290:         }
291:     }
292: 
293:     if (matched_books.empty()) {
294:         return {};
295:     }
296: 
297:     std::vector<Index> matches;
298:     for (const std::string& word : words) {
299:         const auto& indices = inverted_index.at(word);
300: 
301:         for (const Index& index : indices) {
302:             if (matched_books.contains(index.book_id)) {
303:                 matches.push_back(index);
304:             }
305:         }
306:     }
307: 
308:     std::ranges::sort(matches, {}, cmpr);
309: 
310:     return matches;
311: }
