313: std::vector<Index> SearchEngine::search_phrase(std::string_view query) const {
314:     const std::vector<std::string> words = tokenize(query);
315:     if (words.empty()) {
316:         return {};
317:     }
318: 
319:     const auto first_word = inverted_index.find(words.front());
320:     if (first_word == inverted_index.end()) {
321:         return {};
322:     }
323: 
324:     std::vector<Index> matches;
325:     for (const Index& start : first_word->second) {
326:         std::vector<Index> phrase_match{start};
327:         bool is_phrase = true;
328: 
329:         for (size_t offset = 1; offset < words.size(); ++offset) {
330:             const auto found = inverted_index.find(words[offset]);
331:             if (found == inverted_index.end()) {
332:                 return {};
333:             }
334: 
335:             const auto next = std::ranges::find_if(found->second, [&](const Index& index) {
336:                 return index.book_id == start.book_id && index.chapter_id == start.chapter_id &&
337:                        index.line == start.line && index.word_idx == start.word_idx + offset;
338:             });
339: 
340:             if (next == found->second.end()) {
341:                 is_phrase = false;
342:                 break;
343:             }
344: 
345:             phrase_match.push_back(*next);
346:         }
347: 
348:         if (is_phrase) {
349:             matches.insert(matches.end(), phrase_match.begin(), phrase_match.end());
350:         }
351:     }
352: 
353:     std::ranges::sort(matches, {}, cmpr);
354:     return matches;
355: }
