431: std::vector<Index> SearchEngine::search_near(std::string_view query, size_t dis) const {
432:     const std::vector<std::string> words = tokenize(query);
433:     if (words.empty()) {
434:         return {};
435:     }
436: 
437:     if (words.size() == 1) {
438:         return search_or(query);
439:     }
440: 
441:     const std::string& word1 = words[0];
442:     const std::string& word2 = words[1];
443: 
444:     const auto first_word = inverted_index.find(word1);
445:     const auto second_word = inverted_index.find(word2);
446:     if (first_word == inverted_index.end() || second_word == inverted_index.end()) {
447:         return {};
448:     }
