    const auto file = dir / "test.txt";
    {
        std::ofstream out(file);
        out << "Harry Potter went to Hogwarts.\n\nHe met Ron and Hermione on the train.\n";
    }

    SearchEngine engine;
    auto loaded = engine.load_file(file.string());
    if (!loaded || *loaded != 1) {
        std::cerr << "FAIL: load_file\n";
        return 1;
