    std::cout << "\nsearch_with_context results: " << res.size() << "\n";
    for (auto& idx : res) {
        std::cout << "  Index: " << std::format("{}", idx) << "\n";
        auto [prev, cur, next] = engine.get_context(idx);
        std::cout << "    prev: [" << prev << "]\n";
        std::cout << "    cur:  [" << cur << "]\n";
        std::cout << "    next: [" << next << "]\n";
    }

    auto top = engine.get_top_words(5);
    std::cout << "\nTop 5 words:\n";
    for (auto& w : top) std::cout << "  " << w << "\n";

    if (res.empty()) {
        std::cerr << "FAIL: search returned empty\n";
        return 2;
    }

    auto [prev, cur, next] = engine.get_context(res[0]);
    if (cur.empty()) {
        std::cerr << "FAIL: context empty\n";
        return 3;
    }

    // Test menu_con.entry rebuild pattern
    auto entries = res | std::views::transform([](const Index& ele) {
        return std::format("{}", ele);
    }) | std::ranges::to<std::vector<std::string>>();
    std::cout << "\nMenu entries:\n";
    for (auto& e : entries) std::cout << "  " << e << "\n";

    if (entries.empty()) {
        std::cerr << "FAIL: menu entries empty\n";
        return 4;
    }

    std::cout << "\nALL OK\n";
    return 0;
}
