#include <vector>

// Simulate exactly what the TUI's add_fn and book_fn do
int main() {
    SearchEngine engine;
    std::string data_path = "data/";

    // Simulate add_fn: list files
    auto cur_files = engine.list_book_files(data_path);
    if (!cur_files) {
        std::cerr << "FAIL: list_book_files error\n";
        return 1;
    }
    std::cout << "add_fn: found " << cur_files->size() << " files\n";

    // Simulate book_fn for first file
    if (!cur_files->empty()) {
        std::string path = (*cur_files)[0];
        std::cout << "book_fn: loading " << path << "\n";
        auto res = engine.load_file(path);
        if (!res) {
            std::cerr << "FAIL: load_file returned error, code="
                      << static_cast<int>(res.error().error)
                      << " errno=" << res.error().sys_errno << "\n";
            return 2;
        }
        std::cout << "book_fn: load_file OK, result=" << *res << "\n";
    }

    // Now simulate search after Add
    auto books = engine.get_books();
    std::cout << "Loaded books: " << books.size() << "\n";

    auto hits = engine.search_with_context(
        SearchRequest{.mode = SearchMode::Or, .query = "potter"});
    std::cout << "Search 'potter': " << hits.size() << " hits\n";

    if (hits.empty()) {
        std::cerr << "FAIL: search returns empty despite loaded book\n";
        return 3;
    }

    auto [prev, cur, next] = engine.get_context(hits[0]);
    std::cout << "Context: " << cur << "\n";

    std::cout << "\nTUI Add flow works correctly\n";
    return 0;
}
